package com.vyron.assistant;
import android.app.Service;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.TextView;
public class FloatingOrbService extends Service{WindowManager wm;View orb;WindowManager.LayoutParams p;public void onCreate(){super.onCreate();if(!Settings.canDrawOverlays(this)){stopSelf();return;}wm=(WindowManager)getSystemService(WINDOW_SERVICE);TextView v=new TextView(this);v.setText("V");v.setTextColor(-1);v.setTextSize(23);v.setTypeface(null,1);v.setGravity(17);GradientDrawable d=new GradientDrawable();d.setShape(1);d.setColor(Color.rgb(11,43,72));d.setStroke(4,Color.rgb(63,220,255));v.setBackground(d);int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;p=new WindowManager.LayoutParams(64,64,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.END;p.x=20;p.y=250;v.setOnClickListener(x->{Intent i=getPackageManager().getLaunchIntentForPackage(getPackageName());if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}});v.setOnTouchListener(new View.OnTouchListener(){int sx,sy;float dx,dy;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){sx=p.x;sy=p.y;dx=e.getRawX();dy=e.getRawY();return true;}if(e.getAction()==2){p.x=sx+(int)(dx-e.getRawX());p.y=sy+(int)(e.getRawY()-dy);try{wm.updateViewLayout(orb,p);}catch(Exception ignored){}return true;}if(e.getAction()==1){if(Math.abs(e.getRawX()-dx)<8&&Math.abs(e.getRawY()-dy)<8)v.performClick();return true;}return false;}});orb=v;try{wm.addView(orb,p);}catch(Exception e){stopSelf();}}public int onStartCommand(Intent i,int f,int id){return START_NOT_STICKY;}public void onDestroy(){if(wm!=null&&orb!=null)try{wm.removeView(orb);}catch(Exception ignored){}super.onDestroy();}public IBinder onBind(Intent i){return null;}}
